test('cancelled unknown send remains pinned until late object appears, never copies or attaches again', async () => {
    const storage = new Storage(), original = await ready(storage); storage.failBefore = true;
    await replaceAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original, { storage, cleanup });
    const result = await cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, await cancellation(), { storage });
    assert.deepEqual(result.coverOperation, { state: 'cancelled', cleanupPending: true });
    const operation = await coverOps().findOne({ operationId: original.operationId });
    assert.equal(operation!.stage, 'sent'); assert.equal(operation!.identity, null);
    storage.failBefore = false;
    await reconcileAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, { storage });
    assert.equal(storage.copies, 1); assert.equal((await ownerRecord())!.coverArtId, oldImage.toHexString());
    storage.objects.set(operation!.target.key, { etag: '"late-object"', versionId: 'late-version' });
    const done = await reconcileAdminCatalogCover(other.toHexString(), 'artist', artist.toHexString(), original.operationId, { storage });
    assert.deepEqual(done.coverOperation, { state: 'cancelled', cleanupPending: false });
    assert.equal(storage.copies, 1); assert.equal(storage.objects.size, 1);
    assert.equal((await ownerRecord())!.coverArtId, oldImage.toHexString());
});
test('another current administrator can cancel expired approval after original role loss and recover a missing owner', async () => {
    const storage = new Storage(), original = await staleCopy(storage);
    await coverOps().updateOne({ operationId: original.operationId }, { $set: { grantExpiresAt: new Date(0) } });
    await getDb()!.collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    await getDb()!.collection('artists').deleteOne({ _id: artist });
    assert.equal((await listAdminCatalogCoverOperations(other.toHexString(), 'artist', artist.toHexString())).items.length, 1);
    const intent = { operationId: randomUUID(), expectedRevision: null };
    await assert.rejects(cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, intent, { storage }),
        (error: any) => error.code === 'ADMIN_PERMISSION_REQUIRED');
    await assert.rejects(cancelAdminCatalogCover(other.toHexString(), 'artist', artist.toHexString(), original.operationId,
        { ...intent, expectedRevision: original.expectedRevision }, { storage }), (error: any) => error.code === 'ADMIN_CATALOG_REVISION_CONFLICT');
    const result = await cancelAdminCatalogCover(other.toHexString(), 'artist', artist.toHexString(), original.operationId, intent, { storage });
    assert.equal(result.item, null); assert.deepEqual(result.coverOperation, { state: 'cancelled', cleanupPending: false });
    assert.equal(await getDb()!.collection('imageAssets').countDocuments(), 1); // The former confirmed cover is not this cancellation's object.
});
test('cancellation rejects stale/null approval, attached operation, reused operation key and an in-flight lease', async () => {
    const storage = new Storage(), original = await staleCopy(storage), intent = await cancellation();
    for (const expectedRevision of [null, original.expectedRevision]) await assert.rejects(
        cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId,
            { ...intent, expectedRevision }, { storage }), (error: any) => error.code === 'ADMIN_CATALOG_REVISION_CONFLICT');
    await assert.rejects(cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId,
        { ...intent, operationId: original.operationId }, { storage }), (error: any) => error.code === 'ADMIN_CATALOG_IDEMPOTENCY_CONFLICT');
    await coverOps().updateOne({ operationId: original.operationId }, { $set: { leaseOwner: 'active-worker', leaseUntil: new Date(Date.now() + 60_000) } });
    await assert.rejects(cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, intent, { storage }),
        (error: any) => error.code === 'ADMIN_CATALOG_COVER_ACTIVE');
    assert.equal((await coverOps().findOne({ operationId: original.operationId }))!.state, 'needsAttention');
    await coverOps().updateOne({ operationId: original.operationId }, { $set: { leaseUntil: null } });
    await cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, intent, { storage });
    const clearIntent = { operationId: randomUUID(), expectedRevision: intent.expectedRevision };
    await clearAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), clearIntent, { storage, cleanup });
    await assert.rejects(cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), clearIntent.operationId,
        await cancellation(), { storage }), (error: any) => error.code === 'ADMIN_CATALOG_COVER_ALREADY_ATTACHED');
});
test('cancelled cleanup revalidates replacement identity and remains recoverable after cancellation actor loses role', async () => {
    const storage = new Storage(), original = await staleCopy(storage), intent = await cancellation(); storage.failDelete = true;
    await cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, intent, { storage });
    const operation = await coverOps().findOne({ operationId: original.operationId });
    const correct = storage.objects.get(operation!.target.key)!;
    storage.objects.set(operation!.target.key, { etag: '"different"', versionId: 'different-version' }); storage.failDelete = false;
    const conflict = await reconcileAdminCatalogCover(other.toHexString(), 'artist', artist.toHexString(), original.operationId, { storage });
    assert.equal(conflict.coverOperation.cleanupPending, true); assert.equal(storage.objects.size, 2);
    await getDb()!.collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    storage.objects.set(operation!.target.key, correct);
    const recovered = await reconcileAdminCatalogCover(other.toHexString(), 'artist', artist.toHexString(), original.operationId, { storage });
    assert.equal(recovered.coverOperation.cleanupPending, false); assert.equal(storage.objects.size, 1);
});
test('expired approval never attaches a completed copy, while committed cover cleanup does not require the old grant', async () => {
    const storage = new Storage(), original = await ready(storage);
    storage.afterCopy = async () => { await coverOps().updateOne({ operationId: original.operationId }, { $set: { grantExpiresAt: new Date(0) } }); };
    const expired = await replaceAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original, { storage, cleanup });
    assert.equal(expired.coverOperation.state, 'needsAttention'); assert.equal((await ownerRecord())!.coverArtId, oldImage.toHexString());
    assert.ok((await coverOps().findOne({ operationId: original.operationId }))!.identity);
    await cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, await cancellation(), { storage });
    storage.afterCopy = undefined;
    const next = await ready(storage); let fail = true;
    const deps = { storage, cleanup: async (id: string) => { if (fail) throw new Error(); await cleanup(id); } };
    const attached = await replaceAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), next, deps);
    assert.deepEqual(attached.coverOperation, { state: 'complete', cleanupPending: true });
    await coverOps().updateOne({ operationId: next.operationId }, { $set: { grantExpiresAt: new Date(0) } });
    fail = false; const recovered = await reconcileAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), next.operationId, deps);
    assert.deepEqual(recovered.coverOperation, { state: 'complete', cleanupPending: false });
});

test('newly approved cover survives older cancelled cleanup debt and its original-key replays', async () => {
    const storage = new Storage(), original = await staleCopy(storage), intent = await cancellation(); storage.failDelete = true;
    const cancelled = await cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, intent, { storage });
    assert.equal(cancelled.coverOperation.cleanupPending, true);
    const source = await getAdminImport(actor.toHexString(), original.importId);
    const next = { ...original, operationId: randomUUID(), expectedRevision: cancelled.item!.revision, expectedSourceRevision: source.item.revision };
    const attached = await replaceAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), next, { storage, cleanup });
    assert.equal(attached.coverOperation.state, 'complete'); assert.equal(storage.copies, 2); assert.equal(storage.objects.size, 3);
    const currentCover = (await ownerRecord())!.coverArtId;
    storage.failDelete = false;
    const recovered = await reconcileAdminCatalogCover(other.toHexString(), 'artist', artist.toHexString(), original.operationId, { storage });
    assert.deepEqual(recovered.coverOperation, { state: 'cancelled', cleanupPending: false });
    assert.equal((await ownerRecord())!.coverArtId, currentCover); assert.ok(storage.objects.has(`images/${currentCover}`));
    assert.equal(storage.objects.size, 2);
    const replay = await replaceAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original, { storage, cleanup });
    assert.equal(replay.coverOperation.state, 'cancelled'); assert.equal(storage.copies, 2);
    assert.equal((await ownerRecord())!.coverArtId, currentCover);
});

test('cover grant is rechecked after HEAD and before dispatch; reserved cancellation safely releases the source pin', async () => {
    const storage = new Storage(), original = await ready(storage), head = storage.head.bind(storage);
    storage.head = async target => {
        const result = await head(target);
        if (target.bucket === 'catalog') await coverOps().updateOne({ operationId: original.operationId },
            { $set: { grantExpiresAt: new Date(0) } });
        return result;
    };
    const expired = await replaceAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original, { storage, cleanup });
    assert.equal(expired.coverOperation.state, 'needsAttention'); assert.equal(storage.copies, 0);
    assert.equal((await coverOps().findOne({ operationId: original.operationId }))!.stage, 'reserved');
    const result = await cancelAdminCatalogCover(actor.toHexString(), 'artist', artist.toHexString(), original.operationId, await cancellation(), { storage });
    assert.deepEqual(result.coverOperation, { state: 'cancelled', cleanupPending: false });
    const source = await getAdminImport(actor.toHexString(), original.importId);
    const cleared = await cleanupAdminImportAsset(actor.toHexString(), original.importId, 'cover',
        { operationId: randomUUID(), expectedRevision: source.item.revision }, storage);
    assert.equal(cleared.item.assets[0].state, 'deleted'); assert.equal(storage.objects.size, 0);
});
